insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('morning-intention-and-evening-review-card', 'Morning Intention and Evening Review Card', 'worksheet'::resource_kind, 'A two-sided card with one intention for the morning and a short look back at night.', 'Use it to help a client start and end the day with a little deliberate attention.', array['Adults']::text[], 'Five minutes daily for one week', 'Keep it small: one intention, one honest look back. Clients tend to grade themselves, so invite them to note what happened rather than how well they did. Bring the card back and let the client pick what to keep.', '[{"id": "f0", "type": "textarea", "label": "This morning my one intention is:"}, {"id": "f1", "type": "textarea", "label": "What might get in the way, and what I will do then:"}, {"id": "f2", "type": "textarea", "label": "Tonight, what happened with my intention?"}, {"id": "f3", "type": "textarea", "label": "One thing I want to carry into tomorrow:"}]'::jsonb, array['daily reflection', 'intention', 'routine']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('boundary-script-fill-in-page', 'Boundary Script Fill-In Page', 'worksheet'::resource_kind, 'A fill-in page for drafting a short, clear boundary statement before a hard conversation.', 'Use it to help a client put a boundary into their own plain words ahead of time.', array['Adults', 'Teens']::text[], '25 minutes', 'Draft in session using a real situation the client chose. Aim for two sentences, no apology and no essay. Rehearse aloud once. Whether and when they say it is their decision.', '[{"id": "f0", "type": "textarea", "label": "The situation where I need a boundary:"}, {"id": "f1", "type": "textarea", "label": "What I need, in one sentence:"}, {"id": "f2", "type": "textarea", "label": "What I am willing to do instead:"}, {"id": "f3", "type": "textarea", "label": "What I will say if the person pushes back:"}, {"id": "f4", "type": "textarea", "label": "Who I could tell after I have tried it:"}]'::jsonb, array['boundaries', 'assertiveness', 'communication']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('weekly-reset-brain-dump-sheet', 'Weekly Reset Brain Dump Sheet', 'worksheet'::resource_kind, 'A sheet for emptying the mind onto paper and sorting it into do, delegate, drop and later.', 'Use it to help a client lower mental clutter and pick next steps.', array['Adults']::text[], '20 minutes weekly', 'Let the client dump first without sorting, then sort together. Many will want to do everything this week, so ask them to circle just three. Revisit weekly and see what the client wants to change about the sorting.', '[{"id": "f0", "type": "textarea", "label": "Everything on my mind right now:"}, {"id": "f1", "type": "textarea", "label": "What I will do this week (circle three):"}, {"id": "f2", "type": "textarea", "label": "What someone else could do or help with:"}, {"id": "f3", "type": "textarea", "label": "What I can let go of:"}, {"id": "f4", "type": "textarea", "label": "What can wait until later:"}]'::jsonb, array['organization', 'weekly review', 'mental load']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('energy-givers-and-drainers-inventory', 'Energy Givers and Drainers Inventory', 'worksheet'::resource_kind, 'An inventory of the people, places and tasks that add or take energy in a client''s week.', 'Use it to help a client notice patterns in what fuels or drains them.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client fill in both columns from the past week, not from what they think they should say. Look for items that could shift by a little, such as timing or company. Keep it descriptive, and let the client choose any change.', '[{"id": "f0", "type": "textarea", "label": "Things that gave me energy this week:"}, {"id": "f1", "type": "textarea", "label": "Things that drained me this week:"}, {"id": "f2", "type": "textarea", "label": "Anything that is on both lists:"}, {"id": "f3", "type": "textarea", "label": "One small change in the amount or timing of something:"}]'::jsonb, array['energy', 'self-care', 'balance']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('plan-b-backup-options-page', 'Plan B Backup Options Page', 'worksheet'::resource_kind, 'A page that lays out a backup plan for a day, event or goal that might not go as hoped.', 'Use it to help a client feel less stuck when a first plan falls through.', array['Adults', 'Teens']::text[], '20 minutes', 'Pick one plan the client cares about and work through the what-ifs together. The goal is flexibility, not rehearsing disaster, so stop at two backups. Ask what the client would say to a friend in the same spot.', '[{"id": "f0", "type": "textarea", "label": "My plan A is:"}, {"id": "f1", "type": "textarea", "label": "What could get in the way:"}, {"id": "f2", "type": "textarea", "label": "Plan B if that happens:"}, {"id": "f3", "type": "textarea", "label": "Plan C, just in case:"}, {"id": "f4", "type": "textarea", "label": "What I will tell myself if I have to switch plans:"}]'::jsonb, array['flexibility', 'planning', 'problem solving']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('thought-record-mini-for-busy-days', 'Thought Record Mini for Busy Days', 'cbt'::resource_kind, 'A pocket-size thought record with only the steps a client can do in two minutes.', 'Use it to help a client catch and rebalance a thought in the moment.', array['Adults', 'Teens']::text[], 'Two minutes, several times a week', 'Teach the full thought record first, then hand over this short version as a bridge. Check for the hot thought, not the most polite one. Review a few entries together and let the client decide which fit them best.', '[{"id": "f0", "type": "textarea", "label": "What happened, in one line:"}, {"id": "f1", "type": "textarea", "label": "The thought that went through my mind:"}, {"id": "f2", "type": "textarea", "label": "How strong the feeling was (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "Another way to look at it:"}, {"id": "f4", "type": "textarea", "label": "How strong the feeling is now (0 to 10):"}]'::jsonb, array['thought record', 'automatic thoughts', 'CBT']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('forecast-versus-outcome-prediction-tracker', 'Forecast Versus Outcome Prediction Tracker', 'cbt'::resource_kind, 'A tracker that sets a client''s predictions beside what actually happened.', 'Use it to help a client test how often their forecasts match real outcomes.', array['Adults', 'Teens']::text[], 'One week', 'Have the client write the prediction before the event and the outcome afterward. Look at the log together without arguing the point; the data does the work. Some predictions will come true, and that is useful information too.', '[{"id": "f0", "type": "textarea", "label": "The event coming up:"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen:"}, {"id": "f2", "type": "textarea", "label": "How sure I am (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "What actually happened:"}, {"id": "f4", "type": "textarea", "label": "What I notice about my predictions:"}]'::jsonb, array['predictions', 'behavioral experiment', 'prediction']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('rules-and-shoulds-rewrite-page', 'Rules and Shoulds Rewrite Page', 'cbt'::resource_kind, 'A page that turns rigid rules a client lives by into flexible preferences.', 'Use it to help a client loosen demands they place on themselves and others.', array['Adults', 'Teens']::text[], '30 minutes', 'List the client''s shoulds and musts, then ask where each came from and what it costs them. Rewrite with words like prefer or would like. Keep the client in charge of which rules stay.', '[{"id": "f0", "type": "textarea", "label": "A rule I try to live by:"}, {"id": "f1", "type": "textarea", "label": "Where I learned it:"}, {"id": "f2", "type": "textarea", "label": "What it costs me when I follow it strictly:"}, {"id": "f3", "type": "textarea", "label": "A more flexible version:"}, {"id": "f4", "type": "textarea", "label": "How I feel about the flexible version:"}]'::jsonb, array['standards', 'cognitive restructuring', 'flexibility']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('mental-filter-balance-sheet', 'Mental Filter Balance Sheet', 'cbt'::resource_kind, 'A two-column sheet for putting what a client filtered out beside what they noticed.', 'Use it to help a client widen their view of a day that felt all bad.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to describe a day as they remember it, then search for what was left out. Neutral facts count as well as good ones. Do not push positives; invite a fuller picture and let them weigh it.', '[{"id": "f0", "type": "textarea", "label": "What stood out about my day:"}, {"id": "f1", "type": "textarea", "label": "What else happened that I did not give weight to:"}, {"id": "f2", "type": "textarea", "label": "Neutral things that were also true:"}, {"id": "f3", "type": "textarea", "label": "How the day looks with both lists in view:"}]'::jsonb, array['cognitive distortions', 'balanced thinking', 'evidence']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('quick-test-behavioral-experiment-card', 'Quick Test Behavioral Experiment Card', 'cbt'::resource_kind, 'A one-card plan for a small, same-week test of a specific belief.', 'Use it to help a client check a belief against what actually happens.', array['Adults', 'Teens']::text[], 'One week', 'Choose a belief the client can test within days and keep the test small and safe. Set the prediction before the test. Afterward, ask what happened and what the client makes of it, not what it should mean.', '[{"id": "f0", "type": "textarea", "label": "The belief I want to test:"}, {"id": "f1", "type": "textarea", "label": "My prediction, with how sure I am (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "The small test I will try:"}, {"id": "f3", "type": "textarea", "label": "What actually happened:"}, {"id": "f4", "type": "textarea", "label": "What I make of it now:"}]'::jsonb, array['behavioral experiment', 'beliefs', 'experiments']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('leaves-on-a-stream-reflection-log', 'Leaves on a Stream Reflection Log', 'act'::resource_kind, 'A log for practicing letting thoughts float by and noting what the client noticed.', 'Use it to help a client practice watching thoughts without following them.', array['Adults', 'Teens']::text[], 'Ten minutes, several times a week', 'Read the exercise aloud once in session. Clients often judge their practice as wrong when thoughts keep coming; reassure them that noticing is the practice. Keep the log short and curious.', '[{"id": "f0", "type": "textarea", "label": "When and where I practiced:"}, {"id": "f1", "type": "textarea", "label": "Thoughts that floated by:"}, {"id": "f2", "type": "textarea", "label": "A time I got hooked and what I did:"}, {"id": "f3", "type": "textarea", "label": "What I noticed afterward:"}]'::jsonb, array['defusion', 'mindfulness', 'ACT']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('values-wheel-weekly-rating-page', 'Values Wheel Weekly Rating Page', 'act'::resource_kind, 'A wheel of life areas for rating how closely the week matched what matters to the client.', 'Use it to help a client see where their actions and values line up or drift.', array['Adults', 'Teens']::text[], '25 minutes', 'Rate importance and action separately for each area. A gap is information, not failure. Choose one area for a small step and let the client lead on which one that is.', '[{"id": "f0", "type": "textarea", "label": "The areas of life that matter to me most:"}, {"id": "f1", "type": "textarea", "label": "This week I acted in line with them in:"}, {"id": "f2", "type": "textarea", "label": "An area where I drifted:"}, {"id": "f3", "type": "textarea", "label": "One small step I can take in that area:"}, {"id": "f4", "type": "textarea", "label": "What might get in the way, and how I will carry it:"}]'::jsonb, array['values', 'committed action', 'ACT']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('thank-your-mind-practice-page', 'Thank Your Mind Practice Page', 'act'::resource_kind, 'A page for answering the mind''s warnings with thanks and then choosing the next move.', 'Use it to help a client unhook from a bossy thought without arguing with it.', array['Adults', 'Teens']::text[], '15 minutes', 'Practice with a mild thought first. A playful tone helps; this is not sarcasm. Ask what the client wants to do next, with the thought still present. Revisit with a harder thought once they have the knack.', '[{"id": "f0", "type": "textarea", "label": "The thought my mind keeps repeating:"}, {"id": "f1", "type": "textarea", "label": "How I can say thanks to my mind for it:"}, {"id": "f2", "type": "textarea", "label": "What I want to do next, with the thought along for the ride:"}, {"id": "f3", "type": "textarea", "label": "What I noticed after:"}]'::jsonb, array['defusion', 'cognitive fusion', 'willingness']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('willingness-dial-planning-sheet', 'Willingness Dial Planning Sheet', 'act'::resource_kind, 'A dial from unwilling to willing for deciding how much room a client will make for discomfort.', 'Use it to help a client choose a step based on willingness, not on feeling ready.', array['Adults', 'Teens']::text[], '20 minutes', 'Rate willingness for a valued step, then shrink the step until the dial moves. Ask what the discomfort is for. Do not push past what the client picks; their dial is the guide.', '[{"id": "f0", "type": "textarea", "label": "The step I am considering:"}, {"id": "f1", "type": "textarea", "label": "My willingness today (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "What discomfort might come with it:"}, {"id": "f3", "type": "textarea", "label": "A smaller version of the step:"}, {"id": "f4", "type": "textarea", "label": "Why this matters to me:"}]'::jsonb, array['willingness', 'committed action', 'acceptance']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('ideal-day-through-values-page', 'Ideal Day Through Values Page', 'act'::resource_kind, 'A page for describing a day lived close to values and finding one piece of it to try now.', 'Use it to help a client turn values into something concrete to do this week.', array['Adults']::text[], '30 minutes', 'Invite the client to describe an ordinary day in detail, not a fantasy. Then find one slice that is possible this week. If the client says nothing feels possible, shrink it to five minutes.', '[{"id": "f0", "type": "textarea", "label": "What an ideal ordinary day looks like for me:"}, {"id": "f1", "type": "textarea", "label": "Which values show up in it:"}, {"id": "f2", "type": "textarea", "label": "One part of it I could do this week:"}, {"id": "f3", "type": "textarea", "label": "What might get in the way:"}, {"id": "f4", "type": "textarea", "label": "How I will notice I took the step:"}]'::jsonb, array['values', 'committed action', 'small steps']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('half-smile-and-willing-hands-practice-log', 'Half-Smile and Willing Hands Practice Log', 'dbt'::resource_kind, 'A log for practicing body-based acceptance with a relaxed face and open hands.', 'Use it to help a client practice acceptance through the body when the mind resists.', array['Adults', 'Teens']::text[], 'Five minutes daily for one week', 'Demonstrate both postures in session and let the client choose what feels tolerable. The log records when, what was hard and what shifted. It supports willingness; it is not meant to make anyone feel better on command.', '[{"id": "f0", "type": "textarea", "label": "When I tried the practice:"}, {"id": "f1", "type": "textarea", "label": "What was hard that I was resisting:"}, {"id": "f2", "type": "textarea", "label": "What I noticed in my body:"}, {"id": "f3", "type": "textarea", "label": "Did anything shift, even a little?"}]'::jsonb, array['radical acceptance', 'willingness', 'distress tolerance']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('wise-mind-decision-walkthrough', 'Wise Mind Decision Walkthrough', 'dbt'::resource_kind, 'A walkthrough that gathers emotion mind and reasonable mind before a decision.', 'Use it to help a client find the wise-mind choice when feelings and logic pull apart.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client voice emotion mind and reasonable mind in turn, then pause and breathe before asking what wise mind says. It may take a few tries. Do not tell the client the answer.', '[{"id": "f0", "type": "textarea", "label": "The decision I am weighing:"}, {"id": "f1", "type": "textarea", "label": "What emotion mind says:"}, {"id": "f2", "type": "textarea", "label": "What reasonable mind says:"}, {"id": "f3", "type": "textarea", "label": "What wise mind says after a few slow breaths:"}, {"id": "f4", "type": "textarea", "label": "My next step:"}]'::jsonb, array['wise mind', 'decision making', 'core DBT']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('check-the-facts-mini-worksheet', 'Check the Facts Mini Worksheet', 'dbt'::resource_kind, 'A short worksheet for sorting what happened from what a client made of it.', 'Use it to help a client test whether an emotion fits the facts.', array['Adults', 'Teens']::text[], '15 minutes', 'Walk through one recent strong emotion. Separate facts from interpretations and ask what the client predicts. Emotions can be valid even when the facts differ; keep that distinction clear and kind.', '[{"id": "f0", "type": "textarea", "label": "The emotion I felt and how strong it was:"}, {"id": "f1", "type": "textarea", "label": "The facts, as a camera would see them:"}, {"id": "f2", "type": "textarea", "label": "The story I told about it:"}, {"id": "f3", "type": "textarea", "label": "Does the emotion fit the facts?"}, {"id": "f4", "type": "textarea", "label": "If not, what could I do to act effectively?"}]'::jsonb, array['check the facts', 'emotion regulation', 'DBT skills']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('building-mastery-daily-challenge-sheet', 'Building Mastery Daily Challenge Sheet', 'dbt'::resource_kind, 'A sheet for picking one doable challenge a day and noting the sense of accomplishment.', 'Use it to help a client build a sense of competence through steady small wins.', array['Adults', 'Teens']::text[], 'Five minutes daily for one week', 'Pick tasks that are just hard enough. Ask the client to rate sense of mastery before and after. A task that was too easy or too hard is useful feedback for tomorrow''s choice.', '[{"id": "f0", "type": "textarea", "label": "Today''s challenge:"}, {"id": "f1", "type": "textarea", "label": "How hard I expect it to be (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "What I did:"}, {"id": "f3", "type": "textarea", "label": "How much mastery I felt afterward (0 to 10):"}]'::jsonb, array['building mastery', 'emotion regulation', 'skills practice']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('fast-self-respect-script-page', 'FAST Self-Respect Script Page', 'dbt'::resource_kind, 'A page for writing a FAST-style script that keeps self-respect in a hard request or refusal.', 'Use it to help a client stay fair, honest and true to their values when asserting themselves.', array['Adults', 'Teens']::text[], '30 minutes', 'Work through a real situation. Ask where the client usually gives up self-respect, such as over-apologizing. Rehearse the script aloud, then adjust the wording to sound like the client.', '[{"id": "f0", "type": "textarea", "label": "The situation:"}, {"id": "f1", "type": "textarea", "label": "What I will say without over-apologizing:"}, {"id": "f2", "type": "textarea", "label": "Where I stay fair:"}, {"id": "f3", "type": "textarea", "label": "Where I stay true to my values:"}, {"id": "f4", "type": "textarea", "label": "How I will manage my feelings afterward:"}]'::jsonb, array['FAST', 'interpersonal effectiveness', 'self-respect']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('weekly-appreciation-exchange-sheet', 'Weekly Appreciation Exchange Sheet', 'couples'::resource_kind, 'A sheet where each partner notes three specific things they appreciated about the other this week.', 'Use it to help a couple build a habit of noticing the good in each other.', array['Couples']::text[], '15 minutes weekly', 'Each partner fills in their own sheet alone, then they exchange and read aloud. Keep it specific and about actions, not traits. If one partner struggles to find items, start with small everyday ones.', '[{"id": "f0", "type": "textarea", "label": "Partner A: three things I appreciated this week:"}, {"id": "f1", "type": "textarea", "label": "Partner A: what it meant to me when I noticed it:"}, {"id": "f2", "type": "textarea", "label": "Partner B: three things I appreciated this week:"}, {"id": "f3", "type": "textarea", "label": "Partner B: what it meant to me when I noticed it:"}, {"id": "f4", "type": "textarea", "label": "One thing we both want more of:"}]'::jsonb, array['appreciation', 'fondness and admiration', 'couples']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('request-not-criticism-rewrite-page', 'Request Not Criticism Rewrite Page', 'couples'::resource_kind, 'A page where partners turn a complaint into a specific, kind request.', 'Use it to help a couple practice asking for what they need without blame.', array['Couples']::text[], '25 minutes', 'Each partner picks a recurring complaint and rewrites it as an I-feel, I-need, would-you-be-willing request. Practice reading it to each other, then let the listener respond in their own words. Stay with one issue at a time.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the complaint, in my words today:"}, {"id": "f1", "type": "textarea", "label": "Partner A: my request, rewritten:"}, {"id": "f2", "type": "textarea", "label": "Partner B: the complaint, in my words today:"}, {"id": "f3", "type": "textarea", "label": "Partner B: my request, rewritten:"}, {"id": "f4", "type": "textarea", "label": "What was it like to hear it said this way?"}]'::jsonb, array['communication', 'soft startup', 'four horsemen']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('our-calm-reunion-after-work-plan', 'Our Calm Reunion After Work Plan', 'couples'::resource_kind, 'A plan for the first twenty minutes when partners reunite at the end of a day.', 'Use it to help a couple settle into the evening without carrying work stress into each other.', array['Couples']::text[], '20 minutes', 'Each partner says what they need in the first twenty minutes, then they agree on a routine. Revisit after a week and adjust. Watch for one partner doing all the adapting.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I need when I walk in:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I need when I walk in:"}, {"id": "f2", "type": "textarea", "label": "Our reunion routine, in a few steps:"}, {"id": "f3", "type": "textarea", "label": "What each of us will do to help:"}, {"id": "f4", "type": "textarea", "label": "How we will check how it is going:"}]'::jsonb, array['routine', 'connection', 'stress']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('money-talk-agenda-sheet', 'Money Talk Agenda Sheet', 'couples'::resource_kind, 'An agenda for a calm, scheduled conversation about shared money decisions.', 'Use it to help a couple talk about money with a plan instead of in the middle of an argument.', array['Couples']::text[], '30 minutes', 'Set time limits and a topic. Each partner shares what money means to them before any numbers come up. The clinician keeps the focus on understanding, not winning. Revisit monthly.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what money means to me:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what money means to me:"}, {"id": "f2", "type": "textarea", "label": "The one topic we will talk about today:"}, {"id": "f3", "type": "textarea", "label": "What each of us wants to be true a year from now:"}, {"id": "f4", "type": "textarea", "label": "Our next step and when we will check in:"}]'::jsonb, array['money', 'decisions', 'communication']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('weekly-warmth-rituals-calendar-planner', 'Weekly Warmth Rituals Calendar Planner', 'couples'::resource_kind, 'A planner for small repeating moments of connection a couple can count on each week.', 'Use it to help a couple protect time for warmth in an ordinary week.', array['Couples']::text[], '20 minutes', 'Ask each partner for two rituals they would enjoy, such as a morning coffee or a weekly walk. Choose together and put them in the calendar. Small and reliable beats big and rare.', '[{"id": "f0", "type": "textarea", "label": "Partner A: rituals I would enjoy:"}, {"id": "f1", "type": "textarea", "label": "Partner B: rituals I would enjoy:"}, {"id": "f2", "type": "textarea", "label": "The ones we are choosing:"}, {"id": "f3", "type": "textarea", "label": "When each will happen this week:"}, {"id": "f4", "type": "textarea", "label": "What could get in the way and what we will do about it:"}]'::jsonb, array['rituals', 'connection', 'planning']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('feelings-forecast-hanging-mobile-craft', 'Feelings Forecast Hanging Mobile Craft', 'kids'::resource_kind, 'A hanging mobile of paper weather symbols that a child decorates to show feelings.', 'Use it to help a child name feelings and show how they change through the day.', array['Children']::text[], '30 minutes', 'Let the child draw sun, clouds, rain and storm shapes and label each with a feeling. Hang it somewhere visible at home. The parent can point to one symbol daily and ask about it. Follow your reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Which weather feels like me today?"}, {"id": "f1", "type": "textarea", "label": "What feeling goes with the storm cloud?"}, {"id": "f2", "type": "textarea", "label": "What helps when the weather is stormy?"}, {"id": "f3", "type": "textarea", "label": "Who can I tell about my weather?"}]'::jsonb, array['emotion recognition', 'craft', 'children']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('worry-monster-shoebox-home', 'Worry Monster Shoebox Home', 'kids'::resource_kind, 'A decorated shoebox where a child can post their worries to a friendly monster.', 'Use it to help a child set worries down somewhere outside their head.', array['Children']::text[], '30 minutes', 'The child builds the monster and a slot for worry notes. The parent checks the box with the child on a set evening and does not need to fix every note. If a note shows possible harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "What does my worry monster look like?"}, {"id": "f1", "type": "textarea", "label": "A worry I can post tonight:"}, {"id": "f2", "type": "textarea", "label": "What the monster says back, in a funny voice:"}, {"id": "f3", "type": "textarea", "label": "What helps when I wake up worried?"}]'::jsonb, array['worry', 'craft', 'anxiety support']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('bubble-breathing-count-game', 'Bubble Breathing Count Game', 'kids'::resource_kind, 'A game of blowing bubbles slowly and counting how many a child can make in one breath.', 'Use it to help a child practice slow breathing as a game.', array['Children']::text[], '10 minutes', 'Bring bubble solution or a bubble wand with a bowl of water. Slow, steady breaths make the most bubbles. The parent plays along at home. Stop if the child feels dizzy and let them rest.', '[{"id": "f0", "type": "textarea", "label": "How many bubbles I made:"}, {"id": "f1", "type": "textarea", "label": "What my breath felt like:"}, {"id": "f2", "type": "textarea", "label": "What I could do if I feel upset at school:"}, {"id": "f3", "type": "textarea", "label": "What I want to try again at home:"}]'::jsonb, array['breathing', 'calming', 'play']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('superhero-cape-strengths-craft', 'Superhero Cape Strengths Craft', 'kids'::resource_kind, 'A craft where a child decorates a paper cape with their own strengths.', 'Use it to help a child name what they are good at and bring it out when things are hard.', array['Children']::text[], '30 minutes', 'Provide paper or an old pillowcase and markers. Ask what the child does well, including small things like being kind. The parent adds one strength the child did not mention. Let the child choose which to show.', '[{"id": "f0", "type": "textarea", "label": "My superhero name:"}, {"id": "f1", "type": "textarea", "label": "My three strengths:"}, {"id": "f2", "type": "textarea", "label": "Which strength helps when something is hard?"}, {"id": "f3", "type": "textarea", "label": "Who sees my strengths?"}]'::jsonb, array['strengths', 'craft', 'confidence']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('kind-words-jar-decorating-project', 'Kind Words Jar Decorating Project', 'kids'::resource_kind, 'A jar a child decorates and fills with kind notes from family.', 'Use it to help a child collect kind words they can reread on harder days.', array['Children']::text[], 'Decorate in 30 minutes, ongoing notes', 'The child decorates the jar and the parent adds a note each week. Read one together after a hard day. Keep notes specific, such as how the child helped. Let the child keep the jar.', '[{"id": "f0", "type": "textarea", "label": "What my jar looks like:"}, {"id": "f1", "type": "textarea", "label": "A kind word I would put in for someone else:"}, {"id": "f2", "type": "textarea", "label": "A time a kind word helped me:"}, {"id": "f3", "type": "textarea", "label": "When I will read a note from my jar:"}]'::jsonb, array['kindness', 'craft', 'self-esteem']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('reframe-relay-card-game', 'Reframe Relay Card Game', 'game'::resource_kind, 'A team relay where players turn tough thoughts on cards into more balanced ones.', 'Use it to help group members practice reframing with humor and speed.', array['Teens', 'Groups']::text[], '30 minutes', 'Two teams line up. A player draws a tough-thought card, says it and passes a more balanced version to the next player. Rules: no mocking. After, debrief on which reframes felt believable. Use made-up thoughts, not the members'' own.', '[{"id": "f0", "type": "textarea", "label": "The tough thought I drew:"}, {"id": "f1", "type": "textarea", "label": "The balanced version I gave:"}, {"id": "f2", "type": "textarea", "label": "Which reframe felt most believable?"}, {"id": "f3", "type": "textarea", "label": "One I might use this week:"}]'::jsonb, array['cognitive restructuring', 'group', 'game']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('values-acting-out-charades-round', 'Values Acting-Out Charades Round', 'game'::resource_kind, 'A charades game where players act out values and the group guesses them.', 'Use it to help a group talk about values in a playful way.', array['Teens', 'Groups']::text[], '25 minutes', 'Write values on slips and take turns acting them out silently. Rules: no words, ninety seconds, anyone may pass. In the debrief, ask which value players want to act on this week.', '[{"id": "f0", "type": "textarea", "label": "A value I acted out:"}, {"id": "f1", "type": "textarea", "label": "A value that was hard to show:"}, {"id": "f2", "type": "textarea", "label": "Where that value shows up in my week:"}, {"id": "f3", "type": "textarea", "label": "One thing I can do for it:"}]'::jsonb, array['values', 'charades', 'group']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('skill-bingo-night', 'Skill Bingo Night', 'game'::resource_kind, 'A bingo game where each square is a coping skill players try during the week.', 'Use it to help a group try new coping skills with a friendly nudge.', array['Teens', 'Groups']::text[], 'One week plus 15 minutes to review', 'Hand out bingo sheets of skills. Players mark a square when they try it. Rule: a try counts even if it did not help. At the next session, share what worked and what did not, with no prizes for the most squares.', '[{"id": "f0", "type": "textarea", "label": "Skills I tried this week:"}, {"id": "f1", "type": "textarea", "label": "Which one I would use again:"}, {"id": "f2", "type": "textarea", "label": "Which one was not for me:"}, {"id": "f3", "type": "textarea", "label": "A skill I would add to the board:"}]'::jsonb, array['coping skills', 'bingo', 'group']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('mindful-minute-scavenger-hunt', 'Mindful Minute Scavenger Hunt', 'game'::resource_kind, 'A scavenger hunt where players find something to see, hear, touch and smell in a room.', 'Use it to help players practice noticing the present moment together.', array['Children', 'Teens', 'Groups']::text[], '15 minutes', 'Give each player a list and a time limit. Rules: look slowly, share finds in turn, no taking things from others. Debrief on what players noticed that they usually miss. Adjust the list for sensory sensitivities.', '[{"id": "f0", "type": "textarea", "label": "What I found with my eyes:"}, {"id": "f1", "type": "textarea", "label": "What I heard:"}, {"id": "f2", "type": "textarea", "label": "What I noticed that I usually miss:"}, {"id": "f3", "type": "textarea", "label": "When I could do this on my own:"}]'::jsonb, array['mindfulness', 'five senses', 'scavenger hunt']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('emotion-pantomime-chain-game', 'Emotion Pantomime Chain Game', 'game'::resource_kind, 'A chain game where players act out an emotion and the next player guesses and passes it on.', 'Use it to help a group build emotion recognition through acting.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Players take turns silently acting an emotion for the next person, who guesses and acts a different one. Rules: no words, no pointing at someone. Debrief on what clues were easy to read and what the body does with each feeling.', '[{"id": "f0", "type": "textarea", "label": "The emotion I acted out:"}, {"id": "f1", "type": "textarea", "label": "The clues that showed it:"}, {"id": "f2", "type": "textarea", "label": "An emotion that was hard to guess:"}, {"id": "f3", "type": "textarea", "label": "Where I feel one of these in my body:"}]'::jsonb, array['emotion recognition', 'body awareness', 'game']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('grounding-menu-by-time-of-day', 'Grounding Menu by Time of Day', 'worksheet'::resource_kind, 'A menu of grounding skills sorted into morning, afternoon and night for a client to keep close.', 'Use it to help a client have a grounding skill ready for the hours they feel least steady.', array['Adults', 'Teens']::text[], '25 minutes', 'Build the menu from skills the client already finds tolerable. It is about steadiness in the present, so it never asks about past events. Revisit when hours change, and let the client choose what stays on it.', '[{"id": "f0", "type": "textarea", "label": "Hours of the day when I feel least steady:"}, {"id": "f1", "type": "textarea", "label": "Grounding skills I can use in the morning:"}, {"id": "f2", "type": "textarea", "label": "Grounding skills for the afternoon:"}, {"id": "f3", "type": "textarea", "label": "Grounding skills for the night:"}, {"id": "f4", "type": "textarea", "label": "Where I will keep this menu:"}]'::jsonb, array['PTSD and trauma', 'grounding', 'stabilization']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('safe-place-imagery-skill-page', 'Safe Place Imagery Skill Page', 'dbt'::resource_kind, 'A page for building a calm, imagined place and the cues that help a client return to it.', 'Use it to help a client practice a short skill for settling the body in the present.', array['Adults', 'Teens']::text[], '20 minutes', 'Build the place with senses only, such as what is seen or heard, not memories of events. Stop if the image brings up distress and switch to an anchoring skill. The client decides what belongs there.', '[{"id": "f0", "type": "textarea", "label": "The place I picture, in a few words:"}, {"id": "f1", "type": "textarea", "label": "What I see, hear and feel there:"}, {"id": "f2", "type": "textarea", "label": "A word or object that brings me back to it:"}, {"id": "f3", "type": "textarea", "label": "What I will do if the image stops feeling calm:"}]'::jsonb, array['PTSD and trauma', 'self-soothe', 'imagery']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('values-beyond-the-past-compass', 'Values Beyond the Past Compass', 'act'::resource_kind, 'A compass page for naming what matters to a client now and choosing a small step toward it.', 'Use it to help a client reconnect with chosen directions at their own pace.', array['Adults']::text[], '25 minutes', 'Keep the focus on present values and today''s steps, not on the story of what happened. Offer a short break any time. Small steps count, and the pace belongs to the client.', '[{"id": "f0", "type": "textarea", "label": "Something that matters to me now:"}, {"id": "f1", "type": "textarea", "label": "A small step in that direction this week:"}, {"id": "f2", "type": "textarea", "label": "What might make it hard on a heavy day:"}, {"id": "f3", "type": "textarea", "label": "Who or what supports me:"}]'::jsonb, array['PTSD and trauma', 'values', 'pacing']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('safe-shield-drawing-for-children', 'Safe Shield Drawing for Children', 'kids'::resource_kind, 'A drawing of a shield with pictures of people, places and things that help a child feel safe.', 'Use it to help a child name what makes them feel safe and who to go to.', array['Children']::text[], '30 minutes', 'The child draws and decorates a shield; the parent or caregiver sees it afterward and learns who is on it. Do not ask the child to draw or tell what happened. If a child discloses harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "The people on my shield:"}, {"id": "f1", "type": "textarea", "label": "The places that feel safe:"}, {"id": "f2", "type": "textarea", "label": "Things that help me feel calm:"}, {"id": "f3", "type": "textarea", "label": "Who I can tell if I feel scared:"}]'::jsonb, array['PTSD and trauma', 'safety', 'drawing', 'children']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('now-versus-then-safety-thought-page', 'Now Versus Then Safety Thought Page', 'cbt'::resource_kind, 'A page for noticing a thought of danger and checking what is true in the room today.', 'Use it to help a client orient to the present when a thought feels like danger.', array['Adults', 'Teens']::text[], '20 minutes', 'Practice with a mild example first. The client names what is around them now, not details of the past. If strong distress appears, pause and return to grounding. Whether to use it is a clinical call for you and the client.', '[{"id": "f0", "type": "textarea", "label": "The thought that felt like danger:"}, {"id": "f1", "type": "textarea", "label": "What I can see and hear in the room right now:"}, {"id": "f2", "type": "textarea", "label": "What is different about today:"}, {"id": "f3", "type": "textarea", "label": "What I can say to myself that is true now:"}]'::jsonb, array['PTSD and trauma', 'orienting', 'thoughts']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('anxiety-staircase-of-small-steps-page', 'Anxiety Staircase of Small Steps Page', 'worksheet'::resource_kind, 'A page where a client lists steps toward something anxiety keeps them from, from easiest to hardest.', 'Use it to help a client plan gradual steps at a pace they choose.', array['Adults', 'Teens']::text[], '30 minutes', 'Have the client name the goal, then fill in steps with a 0 to 10 difficulty. Check the first step is truly small. They choose the pace; you adjust the stairs together.', '[{"id": "f0", "type": "textarea", "label": "What I want to be able to do:"}, {"id": "f1", "type": "textarea", "label": "Steps from easiest to hardest:"}, {"id": "f2", "type": "textarea", "label": "How hard each step feels (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "The first step I will try and when:"}, {"id": "f4", "type": "textarea", "label": "What I will do if it feels like too much:"}]'::jsonb, array['anxiety', 'hierarchy', 'small steps']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('what-else-could-happen-list', 'What Else Could Happen List', 'cbt'::resource_kind, 'A list for generating other likely outcomes beside the one a worried client keeps picturing.', 'Use it to help a client widen the range of outcomes they consider.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask for the feared outcome, then a best case, then the most likely. The aim is range, not forced optimism. Notice when the client treats a possibility as a certainty and name that gently.', '[{"id": "f0", "type": "textarea", "label": "What I am worried will happen:"}, {"id": "f1", "type": "textarea", "label": "The best thing that could happen:"}, {"id": "f2", "type": "textarea", "label": "What is most likely to happen:"}, {"id": "f3", "type": "textarea", "label": "If the hard thing did happen, how I would cope:"}, {"id": "f4", "type": "textarea", "label": "What I will do now:"}]'::jsonb, array['anxiety', 'worry', 'predictions']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('anxiety-passengers-walk-page', 'Anxiety Passengers Walk Page', 'act'::resource_kind, 'A page for taking anxious thoughts along on a walk as passengers while heading somewhere that matters.', 'Use it to help a client act on a value while anxiety comes along.', array['Adults', 'Teens']::text[], '20 minutes', 'Use the bus metaphor on a real destination the client picks. Let them name the passengers and what each says. The focus is on moving, not on getting rid of passengers.', '[{"id": "f0", "type": "textarea", "label": "Where I want to go and why it matters:"}, {"id": "f1", "type": "textarea", "label": "The anxious passengers and what they say:"}, {"id": "f2", "type": "textarea", "label": "What I do with them on board:"}, {"id": "f3", "type": "textarea", "label": "What I noticed as I moved:"}]'::jsonb, array['anxiety', 'passengers on the bus', 'values']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('worry-wipeout-toss-game', 'Worry Wipeout Toss Game', 'game'::resource_kind, 'A game of tossing a soft ball at worry cards and then deciding what to do with each.', 'Use it to help players practice sorting worries into act, let go or plan.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Write worries on cards and tape them to a wall. Rules: one toss per turn, then sort the card into act now, plan for later or let it float. Use made-up worries or ones the player chooses to share. Debrief on which pile is easiest.', '[{"id": "f0", "type": "textarea", "label": "A worry I tossed at:"}, {"id": "f1", "type": "textarea", "label": "Which pile it went in:"}, {"id": "f2", "type": "textarea", "label": "A worry that was hard to sort:"}, {"id": "f3", "type": "textarea", "label": "What I could do with one this week:"}]'::jsonb, array['anxiety', 'worry', 'game']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('soothing-evening-wind-down-plan', 'Soothing Evening Wind-Down Plan', 'dbt'::resource_kind, 'A plan of calming, sensory and kind-to-self steps for the last hour before bed.', 'Use it to help a client settle an anxious body in the evening.', array['Adults', 'Teens']::text[], '20 minutes', 'Build the plan around the senses the client likes. Keep screens and problem-solving out of the last hour where possible. It is a menu, not a rule, so let the client choose and swap.', '[{"id": "f0", "type": "textarea", "label": "What I do now in the last hour before bed:"}, {"id": "f1", "type": "textarea", "label": "Soothing things for my eyes, ears and touch:"}, {"id": "f2", "type": "textarea", "label": "What I will stop doing in that hour:"}, {"id": "f3", "type": "textarea", "label": "My wind-down plan, in order:"}, {"id": "f4", "type": "textarea", "label": "What I will do if worry shows up at night:"}]'::jsonb, array['anxiety', 'self-soothe', 'routine']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('three-small-wins-nightly-log-page', 'Three Small Wins Nightly Log Page', 'worksheet'::resource_kind, 'An evening page for noting three things done today, however small, with what each took.', 'Use it to help a client notice effort on days when mood is low.', array['Adults', 'Teens']::text[], 'Five minutes daily for two weeks', 'Count anything done as a win, including getting out of bed. Expect self-criticism to creep in; ask the client to write what they did, not what they did not. Review patterns together.', '[{"id": "f0", "type": "textarea", "label": "Three things I did today:"}, {"id": "f1", "type": "textarea", "label": "How much effort each took (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "Which one I am glad I did:"}, {"id": "f3", "type": "textarea", "label": "One small thing for tomorrow:"}]'::jsonb, array['depression', 'small steps', 'low mood', 'tracking']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('activity-and-pleasure-prediction-page', 'Activity and Pleasure Prediction Page', 'cbt'::resource_kind, 'A page comparing how much a client predicts they will enjoy an activity with how it went.', 'Use it to help a client test the belief that nothing will be enjoyable.', array['Adults', 'Teens']::text[], 'One week', 'Choose a few simple activities. Have the client predict enjoyment and sense of accomplishment before and rate them after. Compare the numbers together without telling them how they should feel. If thoughts of self-harm appear, address them in session and mention 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "The activity I picked:"}, {"id": "f1", "type": "textarea", "label": "How much I predict I will enjoy it (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "How much I actually enjoyed it (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "What I notice about the difference:"}, {"id": "f4", "type": "textarea", "label": "If my mood feels dangerous, I can call or text 988."}]'::jsonb, array['depression', 'behavioral activation', 'prediction']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('valued-living-tiny-step-chooser', 'Valued Living Tiny Step Chooser', 'act'::resource_kind, 'A page that picks one tiny step toward a value for a low-energy day.', 'Use it to help a client act on a value when motivation is absent.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask what matters, then shrink the step to two minutes. Action before motivation is the idea. Do not argue with low mood; ask what the client wants to do while it is there.', '[{"id": "f0", "type": "textarea", "label": "Something that matters to me:"}, {"id": "f1", "type": "textarea", "label": "A tiny step I can do in two minutes:"}, {"id": "f2", "type": "textarea", "label": "What my mind will say about it:"}, {"id": "f3", "type": "textarea", "label": "When I will do it:"}]'::jsonb, array['depression', 'values', 'committed action']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('low-mood-opposite-action-trial-page', 'Low Mood Opposite Action Trial Page', 'dbt'::resource_kind, 'A page for noticing the urge that comes with low mood and trying an opposite action.', 'Use it to help a client try one small action opposite to the urge to withdraw.', array['Adults', 'Teens']::text[], '20 minutes', 'Check the facts first: does the mood fit the situation? Opposite action fits when it does not help. Have the client choose a step they can manage. If the mood fits, work on acceptance.', '[{"id": "f0", "type": "textarea", "label": "What I feel like doing when my mood is low:"}, {"id": "f1", "type": "textarea", "label": "Does the urge help me?"}, {"id": "f2", "type": "textarea", "label": "A small opposite action:"}, {"id": "f3", "type": "textarea", "label": "What I noticed after trying it:"}]'::jsonb, array['depression', 'opposite action', 'emotion regulation']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('partner-support-plan-for-low-days', 'Partner Support Plan for Low Days', 'couples'::resource_kind, 'A plan where partners agree what helps, what does not and how to check in on low days.', 'Use it to help a couple support each other without taking over.', array['Couples']::text[], '25 minutes', 'The partner with low mood says what helps, and the other says what they can offer and what they need. Agree on a signal. If either partner mentions self-harm, include 988 (call or text) in the plan and discuss it in session.', '[{"id": "f0", "type": "textarea", "label": "The partner with low mood: what helps, what does not:"}, {"id": "f1", "type": "textarea", "label": "The other partner: what I can offer:"}, {"id": "f2", "type": "textarea", "label": "What I need so I do not burn out:"}, {"id": "f3", "type": "textarea", "label": "Our signal for a hard day:"}, {"id": "f4", "type": "textarea", "label": "If it feels unsafe, we can call or text 988 together."}]'::jsonb, array['depression', 'support', 'partners']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('start-button-task-launch-page', 'Start Button Task Launch Page', 'worksheet'::resource_kind, 'A page for breaking the first minute of a hard task into a tiny, concrete launch.', 'Use it to help a client get past the hardest part, which is starting.', array['Adults', 'Teens']::text[], '15 minutes', 'Pick a task the client has put off. Define the first visible action, like opening the file, and set a timer for five minutes. Praise starting, not finishing. The client chooses what to try first.', '[{"id": "f0", "type": "textarea", "label": "The task I am avoiding:"}, {"id": "f1", "type": "textarea", "label": "The very first thing I can do:"}, {"id": "f2", "type": "textarea", "label": "What I need nearby to make it easier:"}, {"id": "f3", "type": "textarea", "label": "How long I will work:"}, {"id": "f4", "type": "textarea", "label": "What I will do when the timer ends:"}]'::jsonb, array['ADHD', 'task initiation', 'executive function']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('wiggle-and-calm-break-menu-craft', 'Wiggle and Calm Break Menu Craft', 'kids'::resource_kind, 'A craft where a child decorates a menu of quick movement and calm breaks.', 'Use it to help a child pick a break that fits when focus slips.', array['Children']::text[], '30 minutes', 'The child draws and writes breaks such as stretching or squeezing a ball. The parent uses the menu at homework time and lets the child choose. Keep breaks to a few minutes.', '[{"id": "f0", "type": "textarea", "label": "Breaks that get my wiggles out:"}, {"id": "f1", "type": "textarea", "label": "Breaks that calm me down:"}, {"id": "f2", "type": "textarea", "label": "How I know it is time for a break:"}, {"id": "f3", "type": "textarea", "label": "What I do when the break is over:"}]'::jsonb, array['ADHD', 'movement', 'craft', 'children']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('focus-freeze-dance-game', 'Focus Freeze Dance Game', 'game'::resource_kind, 'A freeze-dance game where players practice stopping, noticing and returning focus.', 'Use it to help players practice shifting attention on cue.', array['Children', 'Groups']::text[], '15 minutes', 'Play music and call freeze at random. Rules: stop on cue, then name what you notice. Make it silly. Debrief on how it felt to stop and start and what helps them focus at school.', '[{"id": "f0", "type": "textarea", "label": "What was it like to freeze?"}, {"id": "f1", "type": "textarea", "label": "What did I notice when I stopped?"}, {"id": "f2", "type": "textarea", "label": "What helps me get back to work?"}, {"id": "f3", "type": "textarea", "label": "One time I could use freezing this week:"}]'::jsonb, array['ADHD', 'attention', 'game']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('shared-responsibility-reset-chart', 'Shared Responsibility Reset Chart', 'couples'::resource_kind, 'A chart where partners sort household tasks by who does what and what is falling through.', 'Use it to help a couple share the mental load when one partner has trouble with follow-through.', array['Couples']::text[], '30 minutes', 'Each partner lists tasks and what gets missed. Look for systems, such as reminders and shared calendars, before blame. Both partners get a say.', '[{"id": "f0", "type": "textarea", "label": "Partner A: tasks I do now:"}, {"id": "f1", "type": "textarea", "label": "Partner B: tasks I do now:"}, {"id": "f2", "type": "textarea", "label": "What often gets missed:"}, {"id": "f3", "type": "textarea", "label": "A system or reminder that could help:"}, {"id": "f4", "type": "textarea", "label": "How we will check in:"}]'::jsonb, array['ADHD', 'household tasks', 'systems']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('time-estimate-reality-check-page', 'Time Estimate Reality Check Page', 'cbt'::resource_kind, 'A page for comparing guessed time with actual time on everyday tasks.', 'Use it to help a client plan with more realistic time estimates.', array['Adults', 'Teens']::text[], 'One week', 'Pick three recurring tasks. Have the client guess, time and compare. Treat the gap as data, not failure. Then plan with the real number.', '[{"id": "f0", "type": "textarea", "label": "The task:"}, {"id": "f1", "type": "textarea", "label": "How long I guessed:"}, {"id": "f2", "type": "textarea", "label": "How long it actually took:"}, {"id": "f3", "type": "textarea", "label": "What got in the way:"}, {"id": "f4", "type": "textarea", "label": "How I will plan next time:"}]'::jsonb, array['ADHD', 'time management', 'planning']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('urge-surfing-notes-page', 'Urge Surfing Notes Page', 'worksheet'::resource_kind, 'A page for tracking an urge as it rises and passes without acting on it.', 'Use it to help a client see that urges change over time.', array['Adults']::text[], 'As needed, for two weeks', 'Review the notes together. Clients often find urges peak and fall, but do not promise that. Focus on the details of what the client noticed. If substance use or risk is a concern, plan next steps in session.', '[{"id": "f0", "type": "textarea", "label": "The urge, and what set it off:"}, {"id": "f1", "type": "textarea", "label": "How strong it was at the start (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "What I did while it was there:"}, {"id": "f3", "type": "textarea", "label": "How strong it was after 15 minutes:"}, {"id": "f4", "type": "textarea", "label": "What I learned:"}]'::jsonb, array['addiction', 'urges', 'substance use', 'tracking']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('permission-giving-thought-spotter', 'Permission-Giving Thought Spotter', 'cbt'::resource_kind, 'A page for catching thoughts that give permission to use, like just this once.', 'Use it to help a client notice and answer thoughts that open the door to substance use.', array['Adults', 'Teens']::text[], '25 minutes', 'Collect a few of the client''s own thoughts. For each, write what it is trying to get and an answer in their words. Avoid arguing; ask what the thought leads to.', '[{"id": "f0", "type": "textarea", "label": "A thought that gives me permission:"}, {"id": "f1", "type": "textarea", "label": "What it makes me want to do:"}, {"id": "f2", "type": "textarea", "label": "What usually happens next:"}, {"id": "f3", "type": "textarea", "label": "A response I can believe:"}, {"id": "f4", "type": "textarea", "label": "Who I can reach out to:"}]'::jsonb, array['addiction', 'substance use', 'automatic thoughts']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('urge-distress-tolerance-kit-page', 'Urge Distress Tolerance Kit Page', 'dbt'::resource_kind, 'A page for building a small kit of distress tolerance skills for strong urges.', 'Use it to help a client have a plan for riding out the peak of an urge.', array['Adults', 'Teens']::text[], '25 minutes', 'Build the kit with items that suit the client. Try the skills in session so they know what works. The kit supports their decisions; it does not replace a broader plan.', '[{"id": "f0", "type": "textarea", "label": "Skills for my body (cold, movement, breathing):"}, {"id": "f1", "type": "textarea", "label": "Things that distract me for a while:"}, {"id": "f2", "type": "textarea", "label": "People I can contact:"}, {"id": "f3", "type": "textarea", "label": "What I will do first:"}, {"id": "f4", "type": "textarea", "label": "Where I keep this kit:"}]'::jsonb, array['addiction', 'urges', 'distress tolerance']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('willingness-beside-urges-page', 'Willingness Beside Urges Page', 'act'::resource_kind, 'A page for letting an urge be present while choosing an action that fits a value.', 'Use it to help a client choose actions guided by values when urges show up.', array['Adults']::text[], '25 minutes', 'Ask what matters to the client apart from substance use. Name the urge, make room, and choose a step. Avoid shame; urges are experiences, not failures.', '[{"id": "f0", "type": "textarea", "label": "What matters to me beyond substance use:"}, {"id": "f1", "type": "textarea", "label": "The urge I notice:"}, {"id": "f2", "type": "textarea", "label": "How I can make room for it:"}, {"id": "f3", "type": "textarea", "label": "The step I will take instead:"}]'::jsonb, array['addiction', 'values', 'urges', 'substance use']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('trigger-card-planning-game', 'Trigger Card Planning Game', 'game'::resource_kind, 'A card game where players draw situations that could bring on urges and plan responses.', 'Use it to help a group rehearse plans for substance use triggers in a low-pressure way.', array['Teens', 'Groups']::text[], '30 minutes', 'Write generic trigger situations on cards. Rules: draw a card, say one thing you could do, and others add ideas. No pressure to share personal stories. Debrief on which ideas players want to keep.', '[{"id": "f0", "type": "textarea", "label": "The situation I drew:"}, {"id": "f1", "type": "textarea", "label": "What I would do:"}, {"id": "f2", "type": "textarea", "label": "An idea from someone else I liked:"}, {"id": "f3", "type": "textarea", "label": "One thing I will try:"}]'::jsonb, array['addiction', 'triggers', 'substance use', 'game']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('anger-intensity-skills-ladder', 'Anger Intensity Skills Ladder', 'dbt'::resource_kind, 'A ladder pairing skills with how hot anger is, from simmer to boil.', 'Use it to help a client pick a skill that fits how intense anger is.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client rate anger rungs and name body cues. Place quick physical skills at the top and thinking skills lower. Practice picking from it when calm.', '[{"id": "f0", "type": "textarea", "label": "Signs my anger is at a simmer:"}, {"id": "f1", "type": "textarea", "label": "Signs it is at a boil:"}, {"id": "f2", "type": "textarea", "label": "Skills for each level:"}, {"id": "f3", "type": "textarea", "label": "Where I will keep the ladder:"}]'::jsonb, array['anger management', 'distress tolerance', 'de-escalation']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('mad-meter-thermometer-craft-for-kids', 'Mad Meter Thermometer Craft for Kids', 'kids'::resource_kind, 'A craft thermometer a child colors to show anger levels and calm-down actions.', 'Use it to help a child tell how angry they are and choose an action.', array['Children']::text[], '30 minutes', 'The child colors zones and picks a calm-down action for each. The parent keeps a copy and points to the zone in the moment. Follow your reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "What my body does when I start to get mad:"}, {"id": "f1", "type": "textarea", "label": "My zones, from calm to very mad:"}, {"id": "f2", "type": "textarea", "label": "What I do in each zone:"}, {"id": "f3", "type": "textarea", "label": "Who helps me cool down:"}]'::jsonb, array['anger management', 'craft', 'emotion recognition', 'children']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('hot-thought-cool-down-page', 'Hot Thought Cool-Down Page', 'cbt'::resource_kind, 'A page for catching an angry thought and finding a more balanced version.', 'Use it to help a client slow down angry interpretations.', array['Adults', 'Teens']::text[], '20 minutes', 'Pick a recent flash of anger. Name the thought, the demand underneath it, and a different view. Do not argue the client out of anger; look at what it is protecting.', '[{"id": "f0", "type": "textarea", "label": "What happened:"}, {"id": "f1", "type": "textarea", "label": "The thought that made me angry:"}, {"id": "f2", "type": "textarea", "label": "What I was demanding or expecting:"}, {"id": "f3", "type": "textarea", "label": "A different way to look at it:"}, {"id": "f4", "type": "textarea", "label": "What I will do next time:"}]'::jsonb, array['anger management', 'cognitive restructuring', 'anger']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('heated-moment-time-out-agreement', 'Heated Moment Time-Out Agreement', 'couples'::resource_kind, 'An agreement partners write together for pausing a heated moment and returning to it.', 'Use it to help a couple pause arguments and come back with calmer heads.', array['Couples']::text[], '25 minutes', 'Partners agree on a signal, a length of time and who comes back. The pause is not a way to win. Rehearse it once in session. Revisit after the first week.', '[{"id": "f0", "type": "textarea", "label": "Our signal for a time-out:"}, {"id": "f1", "type": "textarea", "label": "How long we take and what each of us does:"}, {"id": "f2", "type": "textarea", "label": "Who comes back to the conversation and when:"}, {"id": "f3", "type": "textarea", "label": "What we say when we return:"}]'::jsonb, array['anger management', 'de-escalation', 'couples']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('aftermath-repair-reflection-sheet', 'Aftermath Repair Reflection Sheet', 'worksheet'::resource_kind, 'A sheet for reflecting on an angry outburst and planning a repair.', 'Use it to help a client take responsibility and plan a repair after anger.', array['Adults', 'Teens']::text[], '25 minutes', 'Complete it after things have cooled. Keep it factual and avoid shame. Ask what the other person might need to hear. The client decides what to say.', '[{"id": "f0", "type": "textarea", "label": "What happened, in plain words:"}, {"id": "f1", "type": "textarea", "label": "What I felt just before:"}, {"id": "f2", "type": "textarea", "label": "How it affected others:"}, {"id": "f3", "type": "textarea", "label": "What I want to say or do to repair:"}, {"id": "f4", "type": "textarea", "label": "What I will do differently next time:"}]'::jsonb, array['anger management', 'repair', 'responsibility']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('obsession-and-compulsion-cycle-map', 'Obsession and Compulsion Cycle Map', 'worksheet'::resource_kind, 'A map that lays out the trigger, intrusive thought, urge, ritual and short-term relief in a loop.', 'Use it to help a client see how rituals keep the cycle going.', array['Adults', 'Teens']::text[], '30 minutes', 'Fill in one recent cycle together. Avoid reassuring the client about content. Notice the relief step and what it costs later. Next steps are your clinical call with the client.', '[{"id": "f0", "type": "textarea", "label": "The trigger:"}, {"id": "f1", "type": "textarea", "label": "The intrusive thought:"}, {"id": "f2", "type": "textarea", "label": "The urge or ritual I felt:"}, {"id": "f3", "type": "textarea", "label": "What I felt right after:"}, {"id": "f4", "type": "textarea", "label": "What the ritual cost me later:"}]'::jsonb, array['OCD', 'maintenance cycle', 'compulsions']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('thought-is-just-a-thought-defusion-cards', 'Thought Is Just a Thought Defusion Cards', 'act'::resource_kind, 'Cards with phrases for noticing an intrusive thought as a thought and getting on with a valued task.', 'Use it to help a client respond to intrusive thoughts without arguing or checking.', array['Adults', 'Teens']::text[], '20 minutes', 'Write phrases like I am having the thought that on cards in the client''s words. Practice with a mild thought. Arguing with the thought is another ritual; watch for it.', '[{"id": "f0", "type": "textarea", "label": "An intrusive thought that shows up:"}, {"id": "f1", "type": "textarea", "label": "How I can say it as I am having the thought that:"}, {"id": "f2", "type": "textarea", "label": "What I want to do with my time instead:"}, {"id": "f3", "type": "textarea", "label": "What I noticed afterward:"}]'::jsonb, array['OCD', 'defusion', 'intrusive thoughts']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('responsibility-pie-chart-page', 'Responsibility Pie Chart Page', 'cbt'::resource_kind, 'A pie chart page for dividing up who or what shares responsibility for a feared outcome.', 'Use it to help a client see inflated responsibility in perspective.', array['Adults', 'Teens']::text[], '25 minutes', 'Name the feared outcome, list everything that could contribute, then draw slices. Put the client''s share in last. Keep it a conversation, not a debate.', '[{"id": "f0", "type": "textarea", "label": "The outcome I feel responsible for preventing:"}, {"id": "f1", "type": "textarea", "label": "Everyone and everything else that plays a part:"}, {"id": "f2", "type": "textarea", "label": "My slice, drawn last:"}, {"id": "f3", "type": "textarea", "label": "What I notice:"}]'::jsonb, array['OCD', 'responsibility', 'cognitive restructuring']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('bossy-brain-name-and-draw-page', 'Bossy Brain Name and Draw Page', 'kids'::resource_kind, 'A drawing page where a child gives the bossy OCD-like voice a silly name and shape.', 'Use it to help a child separate themselves from the voice that demands rituals.', array['Children']::text[], '30 minutes', 'The child names and draws the bossy voice, then draws themself being brave. The parent learns not to answer the voice with reassurance. Follow your reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "What my bossy brain looks like:"}, {"id": "f1", "type": "textarea", "label": "What it tells me to do:"}, {"id": "f2", "type": "textarea", "label": "What I can say back:"}, {"id": "f3", "type": "textarea", "label": "A brave thing I did:"}]'::jsonb, array['OCD', 'externalizing', 'drawing', 'children']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('uncertainty-tolerance-dice-game', 'Uncertainty Tolerance Dice Game', 'game'::resource_kind, 'A dice game that gives players small not-knowing challenges to sit with.', 'Use it to help a group practice tolerating small uncertainties in a playful way.', array['Teens', 'Groups']::text[], '20 minutes', 'Assign challenges to dice numbers, such as leaving something not perfectly checked. Rules: pick a mild one, no pressure. Debrief on what the discomfort did and whether it passed.', '[{"id": "f0", "type": "textarea", "label": "The number I rolled and the challenge:"}, {"id": "f1", "type": "textarea", "label": "What I felt while sitting with not-knowing:"}, {"id": "f2", "type": "textarea", "label": "What happened to the feeling:"}, {"id": "f3", "type": "textarea", "label": "One more I would try this week:"}]'::jsonb, array['OCD', 'uncertainty', 'game']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('panic-sensation-log-and-meaning-page', 'Panic Sensation Log and Meaning Page', 'worksheet'::resource_kind, 'A log pairing body sensations with what the client thought they meant.', 'Use it to help a client look at the story attached to body sensations.', array['Adults', 'Teens']::text[], 'One week', 'The client records sensations and the meaning they gave them. Look for the jump from sensation to danger. If symptoms are new or worrying, encourage a medical check.', '[{"id": "f0", "type": "textarea", "label": "Where I was and what I was doing:"}, {"id": "f1", "type": "textarea", "label": "The sensations I noticed:"}, {"id": "f2", "type": "textarea", "label": "What I thought they meant:"}, {"id": "f3", "type": "textarea", "label": "What happened next:"}, {"id": "f4", "type": "textarea", "label": "What I noticed afterward:"}]'::jsonb, array['panic attacks', 'body sensations', 'interpretation']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('catastrophe-alternatives-card-for-panic', 'Catastrophe Alternatives Card for Panic', 'cbt'::resource_kind, 'A pocket card with alternative explanations for a racing heart and tight chest.', 'Use it to help a client remember other explanations in the moment.', array['Adults', 'Teens']::text[], '20 minutes', 'Write the client''s own scariest thought and a few alternatives together. Practice reading it when calm. It supports your work and does not replace a medical check when symptoms are new.', '[{"id": "f0", "type": "textarea", "label": "My scariest thought during panic:"}, {"id": "f1", "type": "textarea", "label": "Other explanations for the sensation:"}, {"id": "f2", "type": "textarea", "label": "What I can do right now:"}, {"id": "f3", "type": "textarea", "label": "What I will remind myself:"}]'::jsonb, array['panic attacks', 'catastrophizing', 'cue cards']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('tipp-practice-page-for-peak-moments', 'TIPP Practice Page for Peak Moments', 'dbt'::resource_kind, 'A page for practicing temperature, intense exercise, paced breathing and relaxation.', 'Use it to help a client have a physical skill for peak arousal.', array['Adults', 'Teens']::text[], '25 minutes', 'Try each element in session first, such as cool water on the face. Check medical safety before intense exercise. Note which suits the client best.', '[{"id": "f0", "type": "textarea", "label": "The TIPP skills I tried:"}, {"id": "f1", "type": "textarea", "label": "Which worked best for my body:"}, {"id": "f2", "type": "textarea", "label": "When I will use it:"}, {"id": "f3", "type": "textarea", "label": "What I will do first:"}]'::jsonb, array['panic attacks', 'TIPP', 'distress tolerance']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('wave-rider-surfboard-craft', 'Wave Rider Surfboard Craft', 'kids'::resource_kind, 'A craft where a child decorates a surfboard and rides imagined waves of body feeling.', 'Use it to help a child practice noticing big body feelings rise and fall.', array['Children']::text[], '30 minutes', 'The child draws a wave of feeling and a surfer on top. The parent practices naming the wave with the child. If anything the child says suggests harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "What a big wave feels like in my body:"}, {"id": "f1", "type": "textarea", "label": "What my surfer says to the wave:"}, {"id": "f2", "type": "textarea", "label": "What helps the wave pass:"}, {"id": "f3", "type": "textarea", "label": "Who rides the wave with me:"}]'::jsonb, array['panic attacks', 'craft', 'body sensations', 'children']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('body-alarm-charades', 'Body Alarm Charades', 'game'::resource_kind, 'A charades game where players act out body alarm sensations and what helps.', 'Use it to help a group talk about body sensations in a light way.', array['Teens', 'Groups']::text[], '20 minutes', 'Players act out sensations like a racing heart and the group guesses. Rules: no touching, anyone can pass. Debrief on what players learned about sensations and how they pass.', '[{"id": "f0", "type": "textarea", "label": "A sensation I acted out:"}, {"id": "f1", "type": "textarea", "label": "What it felt like to act it:"}, {"id": "f2", "type": "textarea", "label": "What helps it pass:"}, {"id": "f3", "type": "textarea", "label": "Something I noticed about the sensations:"}]'::jsonb, array['panic attacks', 'body sensations', 'game']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('family-meeting-agenda-page', 'Family Meeting Agenda Page', 'worksheet'::resource_kind, 'An agenda page a family uses to run a short weekly meeting with praise, planning and problems.', 'Use it to help parents build a steady rhythm for talking together.', array['Adults', 'Groups']::text[], '20 minutes weekly', 'Walk the parent through a first meeting. Keep it under twenty minutes and start with appreciations. Let children share the agenda. Adapt it to ages.', '[{"id": "f0", "type": "textarea", "label": "What went well this week:"}, {"id": "f1", "type": "textarea", "label": "Things we need to plan:"}, {"id": "f2", "type": "textarea", "label": "One problem and ideas for it:"}, {"id": "f3", "type": "textarea", "label": "Who does what next week:"}, {"id": "f4", "type": "textarea", "label": "A fun thing we will do together:"}]'::jsonb, array['parenting', 'family', 'routine', 'communication']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('chore-chart-decorating-project', 'Chore Chart Decorating Project', 'kids'::resource_kind, 'A project where a child decorates a chore and routine chart with a parent.', 'Use it to help a family agree on routines in a way a child can own.', array['Children', 'Adults']::text[], '30 minutes', 'The parent and child decorate the chart together and choose age-appropriate tasks. The parent praises effort and keeps tasks few. Follow your reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Jobs I can do at home:"}, {"id": "f1", "type": "textarea", "label": "How I want my chart to look:"}, {"id": "f2", "type": "textarea", "label": "What helps me remember:"}, {"id": "f3", "type": "textarea", "label": "What happens when I finish:"}]'::jsonb, array['parenting', 'routines', 'craft', 'children']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('parents-on-the-same-page-planner', 'Parents on the Same Page Planner', 'couples'::resource_kind, 'A planner for two parents to agree on rules, responses and who handles what.', 'Use it to help parents respond more consistently to their children.', array['Couples']::text[], '30 minutes', 'Each parent writes their top three rules and a typical response. Compare, find overlaps and agree on one thing to try. Keep it private from the children.', '[{"id": "f0", "type": "textarea", "label": "Parent A: three rules that matter to me:"}, {"id": "f1", "type": "textarea", "label": "Parent B: three rules that matter to me:"}, {"id": "f2", "type": "textarea", "label": "Where we agree and where we differ:"}, {"id": "f3", "type": "textarea", "label": "One response we will both use:"}, {"id": "f4", "type": "textarea", "label": "How we will back each other up:"}]'::jsonb, array['parenting', 'co-parenting', 'consistency']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('praise-catch-card-game', 'Praise Catch Card Game', 'game'::resource_kind, 'A family card game where players catch and name specific things others did well.', 'Use it to help a family practice specific praise.', array['Children', 'Groups']::text[], '15 minutes', 'Players take turns drawing a card that asks for a specific compliment. Rules: be specific, no sarcasm. Debrief on how it feels to give and receive praise.', '[{"id": "f0", "type": "textarea", "label": "A compliment I gave:"}, {"id": "f1", "type": "textarea", "label": "A compliment I received:"}, {"id": "f2", "type": "textarea", "label": "How it felt to hear it:"}, {"id": "f3", "type": "textarea", "label": "Someone I will catch doing something well:"}]'::jsonb, array['parenting', 'praise', 'game']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('parent-values-reminder-page', 'Parent Values Reminder Page', 'act'::resource_kind, 'A page for naming the parent a client wants to be and one action that fits it today.', 'Use it to help a parent act on values when things get heated.', array['Adults']::text[], '20 minutes', 'Ask what kind of parent the client wants to be, then link it to an action for the hardest time of day. Acknowledge the pull to react. Keep it nonjudgmental.', '[{"id": "f0", "type": "textarea", "label": "The kind of parent I want to be:"}, {"id": "f1", "type": "textarea", "label": "The hardest time of my day:"}, {"id": "f2", "type": "textarea", "label": "A value-driven response I can try:"}, {"id": "f3", "type": "textarea", "label": "What my mind will tell me then:"}]'::jsonb, array['parenting', 'values', 'parent coaching']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('night-shift-support-plan-for-new-parents', 'Night Shift Support Plan for New Parents', 'worksheet'::resource_kind, 'A plan for sharing night feeds and rest so each parent gets protected sleep blocks.', 'Use it to help new parents protect rest and share care.', array['Adults', 'Couples']::text[], '25 minutes', 'Map the night in detail and see where rest can be protected. Include who steps in when one parent is struggling. If a parent describes feeling unsafe, discuss it in session and mention 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "Who does what between 9 pm and 6 am:"}, {"id": "f1", "type": "textarea", "label": "Where each of us can get a block of sleep:"}, {"id": "f2", "type": "textarea", "label": "Who can step in if we need help:"}, {"id": "f3", "type": "textarea", "label": "What we do if either of us feels overwhelmed:"}, {"id": "f4", "type": "textarea", "label": "If either of us feels unsafe, we can call or text 988."}]'::jsonb, array['perinatal and postpartum', 'sleep', 'support', 'new parents']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('becoming-parents-check-in-conversation', 'Becoming Parents Check-In Conversation', 'couples'::resource_kind, 'A conversation guide for new parents to talk about changes, roles and needs.', 'Use it to help partners stay connected through the shift to parenthood.', array['Couples']::text[], '25 minutes', 'Each partner answers the prompts, then they listen without fixing. Keep it short. Notice where roles have drifted without discussion and let them decide what to change.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what has changed for me:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what has changed for me:"}, {"id": "f2", "type": "textarea", "label": "What I miss and what I enjoy:"}, {"id": "f3", "type": "textarea", "label": "What I need from my partner this week:"}, {"id": "f4", "type": "textarea", "label": "One small thing we will do together:"}]'::jsonb, array['perinatal and postpartum', 'roles', 'connection', 'transition']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('good-enough-day-thought-check', 'Good Enough Day Thought Check', 'cbt'::resource_kind, 'A page for checking perfectionist thoughts about a day of baby care.', 'Use it to help a parent balance harsh judgments of themselves.', array['Adults']::text[], '20 minutes', 'Pick one day and the harshest thought about it. Ask what the baby needed and what a friend would say. Never promise how it should feel. Share your own judgment about when more support is needed.', '[{"id": "f0", "type": "textarea", "label": "The thought I had about myself today:"}, {"id": "f1", "type": "textarea", "label": "What my baby actually needed:"}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend:"}, {"id": "f3", "type": "textarea", "label": "A balanced view:"}]'::jsonb, array['perinatal and postpartum', 'self-criticism', 'perfectionism']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('postpartum-self-soothe-minutes-plan', 'Postpartum Self-Soothe Minutes Plan', 'dbt'::resource_kind, 'A plan for five-minute self-soothing moments built around feeding and naps.', 'Use it to help a new parent find short pockets for steadying skills.', array['Adults']::text[], '20 minutes', 'Find the five minutes available in a typical day. Pick one sensory skill per pocket. Keep it realistic; a parent with a newborn has very little time.', '[{"id": "f0", "type": "textarea", "label": "The pockets of time I actually have:"}, {"id": "f1", "type": "textarea", "label": "A skill for each one:"}, {"id": "f2", "type": "textarea", "label": "What I need nearby to do it:"}, {"id": "f3", "type": "textarea", "label": "How I will remember:"}]'::jsonb, array['perinatal and postpartum', 'self-soothe', 'self-care']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('newborn-fog-values-and-care-moments-page', 'Newborn Fog Values and Care Moments Page', 'act'::resource_kind, 'A page for connecting small daily acts of care to what a new parent values.', 'Use it to help a parent find meaning in ordinary caregiving moments.', array['Adults']::text[], '20 minutes', 'Ask what the client hopes their baby feels around them. Link it to small moments such as a feed or a song. Hard feelings can be there too; make room for them.', '[{"id": "f0", "type": "textarea", "label": "What I hope my baby feels with me:"}, {"id": "f1", "type": "textarea", "label": "A small moment today that showed it:"}, {"id": "f2", "type": "textarea", "label": "What was hard today:"}, {"id": "f3", "type": "textarea", "label": "One thing I will do for myself this week:"}]'::jsonb, array['perinatal and postpartum', 'values', 'meaning']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('meet-the-critic-interview-worksheet', 'Meet the Critic Interview Worksheet', 'worksheet'::resource_kind, 'A page for asking the inner critic what it wants and what it is afraid of.', 'Use it to help a client understand the job their inner critic thinks it has.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client write the critic''s words, then ask what it is trying to prevent. Aim for understanding, not a fight. Then ask what the client wants to say back.', '[{"id": "f0", "type": "textarea", "label": "What my critic says:"}, {"id": "f1", "type": "textarea", "label": "What it is trying to protect me from:"}, {"id": "f2", "type": "textarea", "label": "How it affects me:"}, {"id": "f3", "type": "textarea", "label": "What I want to say back:"}, {"id": "f4", "type": "textarea", "label": "What a kinder voice would add:"}]'::jsonb, array['self-esteem', 'inner critic', 'self-compassion']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('core-belief-evidence-log', 'Core Belief Evidence Log', 'cbt'::resource_kind, 'A log for collecting evidence for and against a belief about self-worth.', 'Use it to help a client look at a core belief against everyday facts.', array['Adults', 'Teens']::text[], 'One week', 'Choose the belief together and write a more balanced version. Log small observations daily. Do not push the new belief; track how much the client believes each.', '[{"id": "f0", "type": "textarea", "label": "The belief I am testing:"}, {"id": "f1", "type": "textarea", "label": "Evidence that supports it today:"}, {"id": "f2", "type": "textarea", "label": "Evidence that does not fit it:"}, {"id": "f3", "type": "textarea", "label": "A more balanced belief:"}, {"id": "f4", "type": "textarea", "label": "How much I believe each (0 to 100):"}]'::jsonb, array['self-esteem', 'core beliefs', 'evidence log']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('self-worth-stories-letting-go-page', 'Self-Worth Stories Letting Go Page', 'act'::resource_kind, 'A page for noticing a self-story and choosing action that fits values.', 'Use it to help a client loosen the grip of a limiting self-story.', array['Adults', 'Teens']::text[], '25 minutes', 'Name the story, give it a title, and notice when it shows up. Ask what the client would do if it were just a story. Choose a small action.', '[{"id": "f0", "type": "textarea", "label": "The story I tell about myself:"}, {"id": "f1", "type": "textarea", "label": "A title for it:"}, {"id": "f2", "type": "textarea", "label": "When it shows up:"}, {"id": "f3", "type": "textarea", "label": "What I would do if it were just a story:"}]'::jsonb, array['self-esteem', 'self-story', 'defusion']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('all-about-me-poster-project', 'All About Me Poster Project', 'kids'::resource_kind, 'A poster a child makes with drawings and words about what they like and do well.', 'Use it to help a child see their own strengths and interests.', array['Children']::text[], '30 minutes', 'Provide markers and magazines to cut up. The child chooses what goes on it. The parent adds something they love about the child. Follow your reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Things I like:"}, {"id": "f1", "type": "textarea", "label": "Things I am good at:"}, {"id": "f2", "type": "textarea", "label": "A time I was brave:"}, {"id": "f3", "type": "textarea", "label": "What my family likes about me:"}]'::jsonb, array['self-esteem', 'strengths', 'craft', 'children']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('strengths-spotlight-seat-game', 'Strengths Spotlight Seat Game', 'game'::resource_kind, 'A group game where players take turns spotlighting a strength they noticed in another player.', 'Use it to help a group practice noticing strengths in others and receiving them.', array['Teens', 'Groups']::text[], '20 minutes', 'Rules: be specific, name what you saw, no putdowns, anyone can pass. Debrief on how it felt to receive. Invite the group to notice who found it hard.', '[{"id": "f0", "type": "textarea", "label": "A strength someone noticed in me:"}, {"id": "f1", "type": "textarea", "label": "A strength I noticed in someone else:"}, {"id": "f2", "type": "textarea", "label": "How it felt to hear mine:"}, {"id": "f3", "type": "textarea", "label": "One strength I will use this week:"}]'::jsonb, array['self-esteem', 'strengths', 'game']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('social-exposure-ladder-planner', 'Social Exposure Ladder Planner', 'worksheet'::resource_kind, 'A ladder of social situations from easiest to hardest with a plan for each step.', 'Use it to help a client plan graded social steps at a pace they choose.', array['Adults', 'Teens']::text[], '30 minutes', 'Build the ladder around the client''s real goals. Start with a step that feels doable. Plan what they will do rather than how they will feel. Review each step and let them choose the next.', '[{"id": "f0", "type": "textarea", "label": "Situations I avoid, from easiest to hardest:"}, {"id": "f1", "type": "textarea", "label": "How anxious each makes me (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "The first step and when I will try it:"}, {"id": "f3", "type": "textarea", "label": "What I will focus on in the moment:"}, {"id": "f4", "type": "textarea", "label": "What I learned:"}]'::jsonb, array['social anxiety', 'hierarchy', 'exposure']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('spotlight-effect-check-page', 'Spotlight Effect Check Page', 'cbt'::resource_kind, 'A page for checking how much others really notice about a client.', 'Use it to help a client test the feeling of being watched.', array['Adults', 'Teens']::text[], 'One week', 'Have the client predict what others will notice and then observe. Include a small experiment. The aim is data, not reassurance.', '[{"id": "f0", "type": "textarea", "label": "What I think people will notice:"}, {"id": "f1", "type": "textarea", "label": "What I observed:"}, {"id": "f2", "type": "textarea", "label": "How closely I think people watch (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "What I make of it now:"}]'::jsonb, array['social anxiety', 'behavioral experiment', 'self-focus']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('social-anxiety-along-for-the-ride-page', 'Social Anxiety Along for the Ride Page', 'act'::resource_kind, 'A page for taking nervous feelings into a social situation while attending to the people there.', 'Use it to help a client act on social values with nerves present.', array['Adults', 'Teens']::text[], '20 minutes', 'Choose a valued social goal. Name the nerves and decide to bring them along. Practice shifting attention outward to the conversation.', '[{"id": "f0", "type": "textarea", "label": "A social goal that matters to me:"}, {"id": "f1", "type": "textarea", "label": "The nerves I expect:"}, {"id": "f2", "type": "textarea", "label": "How I will bring them along:"}, {"id": "f3", "type": "textarea", "label": "Where I will put my attention:"}]'::jsonb, array['social anxiety', 'willingness', 'values']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('brave-hello-sticker-chart-craft', 'Brave Hello Sticker Chart Craft', 'kids'::resource_kind, 'A sticker chart a child decorates for brave hellos and small social steps.', 'Use it to help a child take small social steps and notice them.', array['Children']::text[], '30 minutes', 'The child decorates the chart and picks small steps like saying hi. The parent praises trying, not results. Follow your reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "A brave hello I can try:"}, {"id": "f1", "type": "textarea", "label": "Who I could say it to:"}, {"id": "f2", "type": "textarea", "label": "How it felt:"}, {"id": "f3", "type": "textarea", "label": "My next brave step:"}]'::jsonb, array['social anxiety', 'craft', 'social skills', 'children']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('conversation-starter-spin-game', 'Conversation Starter Spin Game', 'game'::resource_kind, 'A spinner game with conversation prompts players answer and follow up on.', 'Use it to help a group practice starting and keeping a conversation going.', array['Teens', 'Groups']::text[], '25 minutes', 'Make a spinner with simple prompts. Rules: answer, then ask one follow-up question. Anyone can pass once. Debrief on what made talking easier.', '[{"id": "f0", "type": "textarea", "label": "A prompt I answered:"}, {"id": "f1", "type": "textarea", "label": "A follow-up question I asked:"}, {"id": "f2", "type": "textarea", "label": "What made talking easier:"}, {"id": "f3", "type": "textarea", "label": "A conversation I will try this week:"}]'::jsonb, array['social anxiety', 'small talk', 'game']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('grief-waves-weekly-notes-page', 'Grief Waves Weekly Notes Page', 'worksheet'::resource_kind, 'A weekly page for noting when grief rises, what set it off and what helped.', 'Use it to help a client see the rhythm of their grief and what supports them.', array['Adults', 'Teens']::text[], 'Ten minutes weekly', 'Offer it as a way to notice, not to measure or speed up grief. Look together for patterns such as times of day. Grief varies and no pattern is right or wrong.', '[{"id": "f0", "type": "textarea", "label": "When grief came up this week:"}, {"id": "f1", "type": "textarea", "label": "What set it off:"}, {"id": "f2", "type": "textarea", "label": "What helped:"}, {"id": "f3", "type": "textarea", "label": "What I need next week:"}]'::jsonb, array['grief and loss', 'pattern', 'support']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('love-that-continues-values-page', 'Love That Continues Values Page', 'act'::resource_kind, 'A page for naming what a client loved about the person and one way to carry it into their life.', 'Use it to help a client link love and loss to chosen actions.', array['Adults', 'Teens']::text[], '25 minutes', 'Invite stories and values the person stood for. Choose a small action that carries them forward. Make room for sadness; this is not about moving on.', '[{"id": "f0", "type": "textarea", "label": "What I loved about them:"}, {"id": "f1", "type": "textarea", "label": "A value of theirs I want to carry:"}, {"id": "f2", "type": "textarea", "label": "One way to carry it this week:"}, {"id": "f3", "type": "textarea", "label": "What feels hard:"}]'::jsonb, array['grief and loss', 'continuing bonds', 'values']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('keepsake-memory-box-decorating-craft', 'Keepsake Memory Box Decorating Craft', 'kids'::resource_kind, 'A box a child decorates and fills with drawings and small keepsakes of a loved one.', 'Use it to help a child hold memories of someone who has died.', array['Children']::text[], '30 minutes', 'The child decorates the box and picks what goes in. The parent can add a memory. Let the child open it when they want. Follow your reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "What I want to put in my box:"}, {"id": "f1", "type": "textarea", "label": "A favorite memory:"}, {"id": "f2", "type": "textarea", "label": "What I miss:"}, {"id": "f3", "type": "textarea", "label": "Who I can talk to when I miss them:"}]'::jsonb, array['grief and loss', 'memories', 'craft', 'children']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('grieving-together-and-apart-talk-sheet', 'Grieving Together and Apart Talk Sheet', 'couples'::resource_kind, 'A sheet for partners who grieve differently to say what they need.', 'Use it to help a couple make room for different styles of grief.', array['Couples']::text[], '25 minutes', 'Each partner shares how they grieve and what helps, then listens. Normalize difference. Agree on one way to check in.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I grieve:"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I grieve:"}, {"id": "f2", "type": "textarea", "label": "What I need from my partner:"}, {"id": "f3", "type": "textarea", "label": "One way we will check in:"}]'::jsonb, array['grief and loss', 'bereavement', 'partners']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('grief-intensity-self-soothing-plan', 'Grief Intensity Self-Soothing Plan', 'dbt'::resource_kind, 'A plan pairing skills with how heavy a grief wave feels.', 'Use it to help a client have a skill ready for waves of grief.', array['Adults', 'Teens']::text[], '20 minutes', 'Rate grief intensity and match skills. Keep options gentle. Do not aim to stop the sadness; aim to get through the wave.', '[{"id": "f0", "type": "textarea", "label": "Signs a wave is starting:"}, {"id": "f1", "type": "textarea", "label": "Skills for a small wave:"}, {"id": "f2", "type": "textarea", "label": "Skills for a big wave:"}, {"id": "f3", "type": "textarea", "label": "Who I can contact:"}]'::jsonb, array['grief and loss', 'self-soothe', 'distress tolerance']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('pursue-and-withdraw-pattern-map', 'Pursue and Withdraw Pattern Map', 'couples'::resource_kind, 'A map where partners trace how one reaches out and the other pulls back.', 'Use it to help a couple see their cycle as the problem, not each other.', array['Couples']::text[], '30 minutes', 'Each partner shares what they feel and do at each step. Name the cycle together. Avoid blame; look at what each is protecting.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I do when I feel disconnected:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I do when I feel pressure:"}, {"id": "f2", "type": "textarea", "label": "The cycle we fall into:"}, {"id": "f3", "type": "textarea", "label": "What each of us really needs:"}]'::jsonb, array['relationship issues', 'pattern', 'attachment']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('appreciation-before-complaint-starter-page', 'Appreciation Before Complaint Starter Page', 'couples'::resource_kind, 'A page for starting a hard talk with a specific appreciation and a gentle request.', 'Use it to help a couple open hard talks in a softer way.', array['Couples']::text[], '20 minutes', 'Each partner drafts an appreciation and a request. Practice in session. Watch for sarcasm hiding in praise.', '[{"id": "f0", "type": "textarea", "label": "An appreciation I can start with:"}, {"id": "f1", "type": "textarea", "label": "My request, stated simply:"}, {"id": "f2", "type": "textarea", "label": "How I will say it:"}, {"id": "f3", "type": "textarea", "label": "What I will do if it gets heated:"}]'::jsonb, array['relationship issues', 'soft startup', 'communication']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('assumption-check-before-i-react-page', 'Assumption Check Before I React Page', 'cbt'::resource_kind, 'A page for checking an assumption about a partner before acting on it.', 'Use it to help a client separate what happened from what they assumed.', array['Adults']::text[], '15 minutes', 'Pick a recent conflict. Write the assumption and possible other reasons. Plan a question to ask. The client decides whether to bring it up.', '[{"id": "f0", "type": "textarea", "label": "What happened:"}, {"id": "f1", "type": "textarea", "label": "What I assumed:"}, {"id": "f2", "type": "textarea", "label": "Other explanations:"}, {"id": "f3", "type": "textarea", "label": "A question I can ask:"}]'::jsonb, array['relationship issues', 'assumptions', 'mind reading']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('dear-man-script-practice-page', 'DEAR MAN Script Practice Page', 'dbt'::resource_kind, 'A page for writing a DEAR MAN request to a partner, friend or family member.', 'Use it to help a client ask for what they need clearly and respectfully.', array['Adults', 'Teens']::text[], '30 minutes', 'Fill out each letter for a real request and rehearse. Anticipate a no and plan for it. Let the client adapt wording to sound like them.', '[{"id": "f0", "type": "textarea", "label": "Describe the situation:"}, {"id": "f1", "type": "textarea", "label": "Express how I feel:"}, {"id": "f2", "type": "textarea", "label": "Assert what I want:"}, {"id": "f3", "type": "textarea", "label": "Reinforce why it helps:"}, {"id": "f4", "type": "textarea", "label": "Stay mindful, appear confident, negotiate:"}]'::jsonb, array['relationship issues', 'DEAR MAN', 'interpersonal effectiveness']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('two-sides-of-the-story-role-play-game', 'Two Sides of the Story Role-Play Game', 'game'::resource_kind, 'A game where players retell a conflict from each person''s point of view.', 'Use it to help a group practice perspective taking in a conflict.', array['Teens', 'Groups']::text[], '25 minutes', 'Use a made-up conflict card. Rules: tell it from one view, then swap. No blame. Debrief on what each side felt and needed.', '[{"id": "f0", "type": "textarea", "label": "The conflict I drew:"}, {"id": "f1", "type": "textarea", "label": "How person one saw it:"}, {"id": "f2", "type": "textarea", "label": "How person two saw it:"}, {"id": "f3", "type": "textarea", "label": "What I learned about perspective:"}]'::jsonb, array['relationship issues', 'perspective taking', 'game']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('safety-and-support-anchors-plan', 'Safety and Support Anchors Plan', 'worksheet'::resource_kind, 'A plan of people, places and steps that help a client feel safe and supported now.', 'Use it to help a client build a present-focused plan for feeling steady.', array['Adults', 'Teens']::text[], '25 minutes', 'Keep it present-focused and never ask for details of what happened. Let the client choose pace and stop any time. If safety is a concern, work on it in session and name 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "People I trust:"}, {"id": "f1", "type": "textarea", "label": "Places where I feel safe:"}, {"id": "f2", "type": "textarea", "label": "Things that help me feel steady:"}, {"id": "f3", "type": "textarea", "label": "What I do if I feel unsafe (988 is available by call or text):"}]'::jsonb, array['sexual abuse', 'safety', 'support', 'stabilizing']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('pacing-skills-for-hard-days-card', 'Pacing Skills for Hard Days Card', 'dbt'::resource_kind, 'A card of skills for slowing down, grounding and reaching for support on hard days.', 'Use it to help a client choose a stabilizing skill when things feel heavy.', array['Adults', 'Teens']::text[], '20 minutes', 'Practice skills in session when calm. No retelling of events. Let the client lead on pacing and which skills stay on the card.', '[{"id": "f0", "type": "textarea", "label": "Signs it is a hard day:"}, {"id": "f1", "type": "textarea", "label": "Grounding skills I can use:"}, {"id": "f2", "type": "textarea", "label": "People I can reach:"}, {"id": "f3", "type": "textarea", "label": "How I will slow down:"}]'::jsonb, array['sexual abuse', 'pacing', 'grounding']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('today-s-choices-are-mine-values-page', 'Today''s Choices Are Mine Values Page', 'act'::resource_kind, 'A page for naming choices a client can make today that fit their values.', 'Use it to help a client notice agency in everyday decisions.', array['Adults', 'Teens']::text[], '25 minutes', 'Focus on today''s choices, not on the past, and never ask for details of what happened. Celebrate small ones, even deciding what to eat for lunch. The client leads at every step and can pause any time.', '[{"id": "f0", "type": "textarea", "label": "Choices I get to make today:"}, {"id": "f1", "type": "textarea", "label": "Values behind them:"}, {"id": "f2", "type": "textarea", "label": "One I will make this week:"}, {"id": "f3", "type": "textarea", "label": "Who supports me:"}]'::jsonb, array['sexual abuse', 'agency', 'values']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('body-safety-helpers-hand-map', 'Body Safety Helpers Hand Map', 'kids'::resource_kind, 'A hand-shaped map where a child writes or draws trusted helpers on each finger.', 'Use it to help a child name safe adults they can go to.', array['Children']::text[], '25 minutes', 'The child traces a hand and fills each finger with a safe adult. Share the map with the parent or caregiver. If a child discloses harm, follow your reporting duties right away.', '[{"id": "f0", "type": "textarea", "label": "My five safe helpers:"}, {"id": "f1", "type": "textarea", "label": "How I can tell them if I feel unsafe:"}, {"id": "f2", "type": "textarea", "label": "A safe place I can go:"}, {"id": "f3", "type": "textarea", "label": "A word I can use if I need help:"}]'::jsonb, array['sexual abuse', 'safe adults', 'body safety', 'children']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('self-blame-gentle-check-page', 'Self-Blame Gentle Check Page', 'cbt'::resource_kind, 'A page for noticing self-blaming thoughts and a kinder view in the present.', 'Use it to help a client soften self-blame with support.', array['Adults', 'Teens']::text[], '20 minutes', 'Work only with current thoughts, not details of events. Ask what the client would say to a friend. Go at their pace and pause as needed.', '[{"id": "f0", "type": "textarea", "label": "A self-blaming thought I notice:"}, {"id": "f1", "type": "textarea", "label": "How it affects me today:"}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend:"}, {"id": "f3", "type": "textarea", "label": "A kinder thought to try:"}]'::jsonb, array['sexual abuse', 'self-blame', 'self-compassion']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('coping-toolbox-sort-by-situation', 'Coping Toolbox Sort by Situation', 'worksheet'::resource_kind, 'A page for sorting coping skills by the situation they suit best.', 'Use it to help a client match skills to moments.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client list skills and sort them: at home, at work, alone, with others. Fill gaps. Try one in session.', '[{"id": "f0", "type": "textarea", "label": "Skills I already use:"}, {"id": "f1", "type": "textarea", "label": "Where each fits best:"}, {"id": "f2", "type": "textarea", "label": "Gaps where I have nothing:"}, {"id": "f3", "type": "textarea", "label": "One to try this week:"}]'::jsonb, array['coping skills', 'toolbox', 'skills']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('coping-thought-rehearsal-cards', 'Coping Thought Rehearsal Cards', 'cbt'::resource_kind, 'A set of cards with coping thoughts a client writes and rehearses.', 'Use it to help a client have a believable thought ready in a hard moment.', array['Adults', 'Teens']::text[], '20 minutes', 'Write thoughts in the client''s own words so they sound real. Rehearse them aloud. Retire ones that sound false.', '[{"id": "f0", "type": "textarea", "label": "A hard moment I expect:"}, {"id": "f1", "type": "textarea", "label": "A thought that helps me cope:"}, {"id": "f2", "type": "textarea", "label": "How believable it is (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "Where I will keep it:"}]'::jsonb, array['coping skills', 'coping thoughts', 'rehearsal']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('distract-and-soothe-skill-pairing-page', 'Distract and Soothe Skill Pairing Page', 'dbt'::resource_kind, 'A page for pairing distraction skills with soothing skills for different distress levels.', 'Use it to help a client pick both a distraction and a soothing skill.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client pick one of each. Try them in session. Remind them skills buy time, not erase feelings.', '[{"id": "f0", "type": "textarea", "label": "A distraction that works for me:"}, {"id": "f1", "type": "textarea", "label": "A soothing skill that works:"}, {"id": "f2", "type": "textarea", "label": "When I use each:"}, {"id": "f3", "type": "textarea", "label": "What I will try first:"}]'::jsonb, array['coping skills', 'distress tolerance', 'self-soothe']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('coping-skills-bracelet-craft', 'Coping Skills Bracelet Craft', 'kids'::resource_kind, 'A craft where a child makes a beaded bracelet with each color matching a coping skill.', 'Use it to help a child remember coping skills with a hands-on reminder.', array['Children']::text[], '30 minutes', 'The child chooses a color for each skill. The parent asks about the bracelet when the child is upset. Follow your reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "My colors and what each skill is:"}, {"id": "f1", "type": "textarea", "label": "When I will use the bracelet:"}, {"id": "f2", "type": "textarea", "label": "Who I can ask for help:"}, {"id": "f3", "type": "textarea", "label": "A skill I want to add:"}]'::jsonb, array['coping skills', 'craft', 'calm down', 'children']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('coping-skills-pick-a-card-game', 'Coping Skills Pick-a-Card Game', 'game'::resource_kind, 'A card game where players draw a stressful scenario and choose a coping skill.', 'Use it to help a group practice picking coping skills.', array['Children', 'Teens', 'Groups']::text[], '25 minutes', 'Rules: draw a scenario, name a skill, others can add ideas. Anyone can pass. Debrief on skills players want to remember.', '[{"id": "f0", "type": "textarea", "label": "The scenario I drew:"}, {"id": "f1", "type": "textarea", "label": "The skill I picked:"}, {"id": "f2", "type": "textarea", "label": "A skill from someone else:"}, {"id": "f3", "type": "textarea", "label": "One I will use this week:"}]'::jsonb, array['coping skills', 'skills', 'game']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('fear-ladder-with-safety-behavior-notes', 'Fear Ladder With Safety Behavior Notes', 'worksheet'::resource_kind, 'A ladder of feared situations with notes on safety behaviors to drop at each step.', 'Use it to help a client plan gradual steps and notice what they lean on.', array['Adults', 'Teens']::text[], '30 minutes', 'Build the ladder with the client and list what they lean on at each step. Start with a manageable rung. The clinician and client set the pace.', '[{"id": "f0", "type": "textarea", "label": "What I fear, in steps:"}, {"id": "f1", "type": "textarea", "label": "Safety behaviors I use:"}, {"id": "f2", "type": "textarea", "label": "The first step and when I will try it:"}, {"id": "f3", "type": "textarea", "label": "What I learned:"}]'::jsonb, array['phobias', 'fear ladder', 'safety behaviors']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('feared-outcome-probability-review-page', 'Feared Outcome Probability Review Page', 'cbt'::resource_kind, 'A page for looking at what a client fears will happen and what has happened before.', 'Use it to help a client compare predictions with past experience.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the feared outcome and how often it has actually happened. Do not push reassurance. Plan a small test.', '[{"id": "f0", "type": "textarea", "label": "What I fear will happen:"}, {"id": "f1", "type": "textarea", "label": "What has happened before:"}, {"id": "f2", "type": "textarea", "label": "How sure I am (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "A small way to test it:"}]'::jsonb, array['phobias', 'predictions', 'exposure']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('fear-beside-values-crossroads-page', 'Fear Beside Values Crossroads Page', 'act'::resource_kind, 'A page for placing a fear beside the valued life it blocks.', 'Use it to help a client choose steps toward what matters with fear present.', array['Adults', 'Teens']::text[], '25 minutes', 'Name what the fear costs in the client''s life, then link one step to a value. Keep the step small and let the client decide how big it is. Review what happened next time without judging the result.', '[{"id": "f0", "type": "textarea", "label": "What my fear keeps me from:"}, {"id": "f1", "type": "textarea", "label": "Why that matters:"}, {"id": "f2", "type": "textarea", "label": "A step I could take:"}, {"id": "f3", "type": "textarea", "label": "How I will carry the fear:"}]'::jsonb, array['phobias', 'values', 'avoidance']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('fear-fighter-badge-craft', 'Fear Fighter Badge Craft', 'kids'::resource_kind, 'A craft where a child decorates a badge for each brave step toward a fear.', 'Use it to help a child notice and celebrate small brave steps.', array['Children']::text[], '30 minutes', 'The child designs badges. The parent awards one for each step tried, not for results. Follow your reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "A brave step I can try:"}, {"id": "f1", "type": "textarea", "label": "What my badge looks like:"}, {"id": "f2", "type": "textarea", "label": "Who cheers me on:"}, {"id": "f3", "type": "textarea", "label": "What I do when I feel scared:"}]'::jsonb, array['phobias', 'courage', 'craft', 'children']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('brave-path-stepping-board-game', 'Brave Path Stepping Board Game', 'game'::resource_kind, 'A board game where players move forward by doing small brave challenges.', 'Use it to help a group practice small steps toward fears.', array['Children', 'Teens', 'Groups']::text[], '25 minutes', 'Players pick challenge cards matched to their level. Rules: choose your own level, cheer for others. Debrief on what was hard.', '[{"id": "f0", "type": "textarea", "label": "The challenge I tried:"}, {"id": "f1", "type": "textarea", "label": "How scared I felt (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "What happened:"}, {"id": "f3", "type": "textarea", "label": "My next brave step:"}]'::jsonb, array['phobias', 'courage', 'game']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('body-appreciation-letter-page', 'Body Appreciation Letter Page', 'worksheet'::resource_kind, 'A letter page for thanking the body for what it lets a client do.', 'Use it to help a client shift attention to what the body does for them.', array['Adults', 'Teens']::text[], '25 minutes', 'Focus on function, such as hugging or walking. Avoid anything about appearance changes or measuring. Let the client write in their own voice.', '[{"id": "f0", "type": "textarea", "label": "Things my body lets me do:"}, {"id": "f1", "type": "textarea", "label": "A time my body helped me:"}, {"id": "f2", "type": "textarea", "label": "What I want to say to my body:"}, {"id": "f3", "type": "textarea", "label": "One kind thing I will do:"}]'::jsonb, array['body image', 'body', 'gratitude']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('looks-comparison-thought-check-page', 'Looks Comparison Thought Check Page', 'cbt'::resource_kind, 'A page for catching comparing thoughts and answering them.', 'Use it to help a client notice comparison and answer it kindly.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask where the comparing happened, such as social media. Examine the thought and plan changes to what they see. Never mention measuring the body.', '[{"id": "f0", "type": "textarea", "label": "Where I compared myself:"}, {"id": "f1", "type": "textarea", "label": "The thought I had:"}, {"id": "f2", "type": "textarea", "label": "A kinder view:"}, {"id": "f3", "type": "textarea", "label": "A change to what I look at:"}]'::jsonb, array['body image', 'comparison', 'social media']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('valued-life-beyond-looks-page', 'Valued Life Beyond Looks Page', 'act'::resource_kind, 'A page for naming what matters in life apart from appearance.', 'Use it to help a client act on values rather than on appearance worries.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what the client would do if appearance thoughts did not run the day. Choose one small action. Let them lead.', '[{"id": "f0", "type": "textarea", "label": "What matters to me beyond how I look:"}, {"id": "f1", "type": "textarea", "label": "What appearance worries keep me from:"}, {"id": "f2", "type": "textarea", "label": "One valued action this week:"}, {"id": "f3", "type": "textarea", "label": "How I will carry the worry:"}]'::jsonb, array['body image', 'values', 'self-worth']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('mirror-kindness-sticker-craft', 'Mirror Kindness Sticker Craft', 'kids'::resource_kind, 'A craft where a child decorates a mirror card with kind sticker messages.', 'Use it to help a child practice kind words about themselves.', array['Children']::text[], '25 minutes', 'The child decorates a card with kind words about who they are. The parent reads it with them. Keep focus on character and abilities, never appearance. Follow your reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Kind words about who I am:"}, {"id": "f1", "type": "textarea", "label": "What I like to do:"}, {"id": "f2", "type": "textarea", "label": "A kind thing I can say to myself:"}, {"id": "f3", "type": "textarea", "label": "Who I can share my card with:"}]'::jsonb, array['body image', 'self-esteem', 'craft', 'children']::text[], '2026-10-30T15:00:00+00:00'::timestamptz),
  ('character-compliment-circle-game', 'Character Compliment Circle Game', 'game'::resource_kind, 'A game where players give compliments about character and skills.', 'Use it to help a group practice noticing qualities beyond looks.', array['Teens', 'Groups']::text[], '20 minutes', 'Rules: compliments about actions, skills or character only, never about looks. Take turns, and anyone may pass. Debrief on how it felt to give and to receive one.', '[{"id": "f0", "type": "textarea", "label": "A compliment I gave:"}, {"id": "f1", "type": "textarea", "label": "A compliment I received:"}, {"id": "f2", "type": "textarea", "label": "How it felt:"}, {"id": "f3", "type": "textarea", "label": "A quality I like in myself:"}]'::jsonb, array['body image', 'compliments', 'game']::text[], '2026-10-30T15:00:00+00:00'::timestamptz)
